-- Size Normalization Admin System
-- Creates tables for managing conversion tables, category assignments, and normalization history

BEGIN;

-- 1. Conversion tables (named sets of size mappings)
CREATE TABLE IF NOT EXISTS size_conversion_tables (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name VARCHAR(255) NOT NULL,
  description TEXT,
  target_type VARCHAR(20) NOT NULL DEFAULT 'alpha' CHECK (target_type IN ('alpha', 'eu_shoe')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- 2. Individual conversion rows within a table
CREATE TABLE IF NOT EXISTS size_conversion_rows (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  table_id UUID NOT NULL REFERENCES size_conversion_tables(id) ON DELETE CASCADE,
  system VARCHAR(10) NOT NULL,
  source_value VARCHAR(20) NOT NULL,
  target_value VARCHAR(20) NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(table_id, system, source_value)
);
CREATE INDEX IF NOT EXISTS idx_scr_table_id ON size_conversion_rows(table_id);

-- 3. Category-to-table assignment + filter type
CREATE TABLE IF NOT EXISTS category_size_table_map (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  category_id UUID NOT NULL REFERENCES categories(id) ON DELETE CASCADE,
  table_id UUID REFERENCES size_conversion_tables(id) ON DELETE SET NULL,
  filter_type VARCHAR(20) NOT NULL DEFAULT 'alpha' CHECK (filter_type IN ('alpha', 'alpha+numeric', 'shoe', 'numeric', 'us', 'none')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(category_id)
);

-- 4. Normalization run history (audit + rollback)
CREATE TABLE IF NOT EXISTS size_normalization_runs (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  category_id UUID NOT NULL REFERENCES categories(id),
  table_id UUID REFERENCES size_conversion_tables(id),
  admin_id UUID,
  status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'running', 'completed', 'rolled_back', 'failed')),
  stats JSONB,
  backup_table_name VARCHAR(255),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  completed_at TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS idx_snr_category ON size_normalization_runs(category_id);
CREATE INDEX IF NOT EXISTS idx_snr_status ON size_normalization_runs(status);

